cards.solution:
const form = document.querySelector("#komentar");
const daftar = document.querySelector("#daftar");
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const data = Object.fromEntries(new FormData(form));
  const li = document.createElement("li");
  li.textContent = `${data.nama}: ${data.isi}`;
  daftar.append(li);
  form.reset();
});
form.elements.nama.value = "Rina";
form.elements.isi.value = "Materinya jelas!";
form.requestSubmit();
form.elements.nama.value = "Budi";
form.elements.isi.value = "Mantap";
form.requestSubmit();
console.log(daftar.children.length);
console.log(daftar.children[1].textContent);
console.log(`[${form.elements.isi.value}]`);
